def compstats(grid,out,dirs):
 h,w=len(grid),len(grid[0]); t={(r,c) for r in range(h) for c in range(w) if grid[r][c] in (0,7,8)}; seen=set();res=[]
 for p in t:
  if p in seen: continue
  q=[p];seen.add(p);cc=[]
  while q:
   r,c=q.pop();cc.append((r,c))
   for dr,dc in dirs:
    t1=(r+dr,c+dc)
    if t1 in t and t1 not in seen:seen.add(t1);q.append(t1)
  changed=sum(grid[r][c]==0 and out[r][c] in (7,8) for r,c in cc)
  res.append((len(cc),changed,any(grid[r][c] in (7,8) for r,c in cc)))
 return sorted(res,reverse=True)
